// TranscriptionReport defines model for TranscriptionReport.
type TranscriptionReport struct {
	// Enabled Whether a transcription pump is configured at all. Without it, an
	// operator reading `pending: 812` cannot tell a backlog from a service
	// that was never pointed at an ASR endpoint — and those want
	// completely different remedies.
	Enabled    bool       `json:"enabled"`
	Held       int64      `json:"held"`
	HeldSample []HeldMemo `json:"held_sample,omitempty"`

	// Partial Memos whose only transcript is incomplete. Reported because they are
	// otherwise INVISIBLE: a partial memo is `transcribed`, so nothing
	// sweeps it; it is not `held`, so `chronicle retranscribe` will not
	// release it; and its audio correctly does not prune. Every one of
	// those is right, and together they make a partial memo read as a
	// healthy one.
	Partial       int64               `json:"partial"`
	PartialSample []PartialTranscript `json:"partial_sample,omitempty"`

	// Pending Captured, queued and transcribing together. One number, because "how
	// far behind is it" is the question being asked.
	Pending int64 `json:"pending"`

	// States Every memo counted by state, not only the interesting ones. A report
	// naming only `held` could not tell "nothing is wrong" from "nothing
	// is happening", and a pump that has silently stopped looks exactly
	// like a corpus with no failures.
	States map[string]int64 `json:"states"`
}

