	// OpenUploadWithBodyWithResponse Declare an upload and open a session for it.
	//
	// `idempotency_key` is minted per capture and persisted by the client
	// BEFORE the request goes out, so an HTTP retry is a replay rather than a
	// second memo. A replay — same key, same declaration — answers `200` with
	// the existing session.
	//
